"""Persistent HTTP key-value service (dependency-free, Python 3.11+)."""

from __future__ import annotations

import argparse
import json
import os
import signal
import sys
import threading
import time
import urllib.parse
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from typing import Any

MAX_BODY = 1 * 1024 * 1024  # 1 MiB


class KVStore:
    """Thread-safe in-memory KV store with TTL and atomic JSON persistence."""

    def __init__(self, data_path: str) -> None:
        self._data_path = data_path
        self._lock = threading.RLock()
        self._store: dict[str, tuple[Any, float | None]] = {}
        self._load()

    def _load(self) -> None:
        if not os.path.exists(self._data_path):
            return
        try:
            with open(self._data_path, "r", encoding="utf-8") as fh:
                raw = json.load(fh)
            if not isinstance(raw, dict):
                return
            now = time.time()
            for key, entry in raw.items():
                if not isinstance(entry, dict) or "value" not in entry:
                    continue
                ttl = entry.get("ttl_seconds")
                expires_at = entry.get("expires_at")
                if expires_at is not None and expires_at <= now:
                    continue
                self._store[key] = (entry["value"], expires_at)
        except (json.JSONDecodeError, OSError):
            pass

    def _persist_locked(self) -> None:
        now = time.time()
        serializable: dict[str, Any] = {}
        for key, (value, expires_at) in self._store.items():
            if expires_at is not None and expires_at <= now:
                continue
            serializable[key] = {"value": value, "expires_at": expires_at}
        tmp_path = self._data_path + ".tmp"
        with open(tmp_path, "w", encoding="utf-8") as fh:
            json.dump(serializable, fh, ensure_ascii=False)
            fh.flush()
            os.fsync(fh.fileno())
        os.replace(tmp_path, self._data_path)

    def _is_expired(self, expires_at: float | None, now: float | None = None) -> bool:
        if expires_at is None:
            return False
        if now is None:
            now = time.time()
        return expires_at <= now

    def put(self, key: str, value: Any, ttl_seconds: float | None) -> bool:
        """Store value. Returns True if created (new key), False if replaced."""
        with self._lock:
            now = time.time()
            # Purge expired entry for this key first
            existing = self._store.get(key)
            created = existing is None or self._is_expired(existing[1], now)
            expires_at = None
            if ttl_seconds is not None:
                expires_at = now + ttl_seconds
            self._store[key] = (value, expires_at)
            self._persist_locked()
            return created

    def get(self, key: str) -> Any | None:
        with self._lock:
            now = time.time()
            entry = self._store.get(key)
            if entry is None:
                return None
            if self._is_expired(entry[1], now):
                del self._store[key]
                self._persist_locked()
                return None
            return entry[0]

    def delete(self, key: str) -> bool:
        with self._lock:
            now = time.time()
            entry = self._store.get(key)
            if entry is None or self._is_expired(entry[1], now):
                return False
            del self._store[key]
            self._persist_locked()
            return True

    def keys(self) -> list[str]:
        with self._lock:
            now = time.time()
            live = []
            expired = []
            for key, (_, expires_at) in self._store.items():
                if self._is_expired(expires_at, now):
                    expired.append(key)
                else:
                    live.append(key)
            if expired:
                for k in expired:
                    del self._store[k]
                self._persist_locked()
            return sorted(live)


class KVHandler(BaseHTTPRequestHandler):
    server_version = "KVServer/1.0"
    protocol_version = "HTTP/1.1"

    def log_message(self, fmt: str, *args: Any) -> None:
        sys.stderr.write("%s - - [%s] %s\n" % (self.address_string(), self.log_date_time_string(), fmt % args))

    def _send_json(self, status: int, body: Any) -> None:
        payload = json.dumps(body, ensure_ascii=False).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        self.wfile.write(payload)

    def _read_body(self) -> bytes | None:
        try:
            length = int(self.headers.get("Content-Length", 0))
        except (ValueError, TypeError):
            self._send_json(400, {"error": "invalid Content-Length"})
            return None
        if length > MAX_BODY:
            self._send_json(413, {"error": "request body too large"})
            return None
        if length == 0:
            return b""
        data = self.rfile.read(length)
        return data

