        path = urllib.parse.urlparse(self.path).path
        prefix = "/v1/kv/"
        if not path.startswith(prefix):
            return None
        encoded = path[len(prefix):]
        if "/" in encoded:
            return None
        try:
            key = urllib.parse.unquote(encoded, encoding="utf-8")
        except Exception:
            return None
        if key == "":
            return None
        return key

