                return
            if ttl_seconds <= 0 or ttl_seconds == float("inf") or ttl_seconds == float("-inf"):
                self._send_json(400, {"error": "ttl_seconds must be finite and greater than zero"})
                return
        store: KVStore = self.server.store  # type: ignore[attr-defined]
        created = store.put(key, value, ttl_seconds)
        self._send_json(201 if created else 200, {"key": key, "value": value})

    def do_GET(self) -> None:
        path = urllib.parse.urlparse(self.path).path
        if path == "/health":
            self._send_json(200, {"status": "ok"})
            return
        if path == "/v1/keys":
            store: KVStore = self.server.store  # type: ignore[attr-defined]
            self._send_json(200, {"keys": store.keys()})
            return
        key = self._extract_key()
        if key is None:
            self._send_json(404, {"error": "not found"})
            return
        store = self.server.store  # type: ignore[attr-defined]
        value = store.get(key)
        if value is None:
            self._send_json(404, {"error": "key not found"})
            return
        self._send_json(200, {"key": key, "value": value})

    def do_DELETE(self) -> None:
        key = self._extract_key()
        if key is None:
            self._send_json(404, {"error": "not found"})
            return
        store: KVStore = self.server.store  # type: ignore[attr-defined]
        if store.delete(key):
            self.send_response(204)
            self.send_header("Content-Length", "0")
            self.end_headers()
        else:
            self._send_json(404, {"error": "key not found"})

    def do_POST(self) -> None:
        self._send_json(405, {"error": "method not allowed"})

    def do_PATCH(self) -> None:
        self._send_json(405, {"error": "method not allowed"})


class KVServer(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True

    def __init__(self, host: str, port: int, data_path: str) -> None:
        super().__init__((host, port), KVHandler)
        self.store = KVStore(data_path)
        self._shutdown_event = threading.Event()

    def shutdown_signal(self, signum: int, frame: Any) -> None:
        sys.stderr.write(f"Received signal {signum}, shutting down...\n")
        self._shutdown_event.set()
        threading.Thread(target=self.shutdown, daemon=True).start()


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Persistent HTTP key-value service")
    parser.add_argument("--host", default="127.0.0.1", help="bind host")
    parser.add_argument("--port", type=int, default=0, help="bind port (0 = free port)")
    parser.add_argument("--data", required=True, help="path to JSON data file")
    args = parser.parse_args(argv)

    server = KVServer(args.host, args.port, args.data)

    signal.signal(signal.SIGTERM, server.shutdown_signal)
    signal.signal(signal.SIGINT, server.shutdown_signal)

    actual_port = server.server_address[1]
    sys.stdout.write(f"LISTENING {actual_port}\n")
    sys.stdout.flush()

    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()

    return 0


if __name__ == "__main__":
    sys.exit(main())

