class KVHandler(BaseHTTPRequestHandler):
    server_version = "KVServer/1.0"
    protocol_version = "HTTP/1.1"

    def log_message(self, fmt: str, *args: Any) -> None:
        sys.stderr.write("%s - - [%s] %s\n" % (self.address_string(), self.log_date_time_string(), fmt % args))

    def _send_json(self, status: int, body: Any) -> None:
        payload = json.dumps(body, ensure_ascii=False).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        self.wfile.write(payload)

    def _read_body(self) -> bytes | None:
        try:
            length = int(self.headers.get("Content-Length", 0))
        except (ValueError, TypeError):
            self._send_json(400, {"error": "invalid Content-Length"})
            return None
        if length > MAX_BODY:
            self._send_json(413, {"error": "request body too large"})
            return None
        if length == 0:
            return b""
        data = self.rfile.read(length)
        return data

    def _parse_json_body(self) -> Any | None:
        raw = self._read_body()
        if raw is None:
            return None
        if len(raw) == 0:
            self._send_json(400, {"error": "empty body"})
            return None
        try:
            return json.loads(raw)
        except json.JSONDecodeError:
            self._send_json(400, {"error": "malformed JSON"})
            return None

    def _extract_key(self) -> str | None:
        path = urllib.parse.urlparse(self.path).path
        prefix = "/v1/kv/"
        if not path.startswith(prefix):
            return None
        encoded = path[len(prefix):]
        if "/" in encoded:
            return None
        try:
            key = urllib.parse.unquote(encoded, encoding="utf-8")
        except Exception:
            return None
        if key == "":
            return None
        return key

    def do_PUT(self) -> None:
        key = self._extract_key()
        if key is None:
            self._send_json(404, {"error": "not found"})
            return
        body = self._parse_json_body()
        if body is None:
            return
        if not isinstance(body, dict) or "value" not in body:
            self._send_json(400, {"error": "body must be a JSON object with 'value'"})
            return
        value = body["value"]
        ttl_seconds = body.get("ttl_seconds")
        if ttl_seconds is not None:
            if not isinstance(ttl_seconds, (int, float)) or isinstance(ttl_seconds, bool):
                self._send_json(400, {"error": "ttl_seconds must be a number"})
                return
            if ttl_seconds <= 0 or ttl_seconds == float("inf") or ttl_seconds == float("-inf"):
                self._send_json(400, {"error": "ttl_seconds must be finite and greater than zero"})
                return
        store: KVStore = self.server.store  # type: ignore[attr-defined]
        created = store.put(key, value, ttl_seconds)
        self._send_json(201 if created else 200, {"key": key, "value": value})

    def do_GET(self) -> None:
        path = urllib.parse.urlparse(self.path).path
        if path == "/health":
            self._send_json(200, {"status": "ok"})
            return
        if path == "/v1/keys":
